# Inspects a GLB or a .blend: objects, triangle counts, loose parts, materials, images, UV maps, bounds.
# Usage: blender -b --factory-startup --python inspect_glb.py -- <file.glb|file.blend>
import bpy, bmesh, sys
path = sys.argv[sys.argv.index("--") + 1]
if path.lower().endswith(".blend"):
    bpy.ops.wm.open_mainfile(filepath=path)
else:
    bpy.ops.wm.read_factory_settings(use_empty=True)
    bpy.ops.import_scene.gltf(filepath=path)

for o in bpy.context.scene.objects:
    print("OBJ", o.name, o.type, "parent", o.parent.name if o.parent else None,
          "loc", tuple(round(v, 4) for v in o.location), "scale", tuple(round(v, 4) for v in o.scale))
    if o.type != "MESH":
        continue
    me = o.data
    tris = sum(len(p.vertices) - 2 for p in me.polygons)
    bm = bmesh.new(); bm.from_mesh(me)
    seen = set(); parts = 0
    for v in bm.verts:
        if v.index in seen:
            continue
        parts += 1
        stack = [v]; seen.add(v.index)
        while stack:
            a = stack.pop()
            for e in a.link_edges:
                b = e.other_vert(a)
                if b.index not in seen:
                    seen.add(b.index); stack.append(b)
    boundary = sum(1 for e in bm.edges if len(e.link_faces) == 1)
    nonman = sum(1 for e in bm.edges if len(e.link_faces) > 2)
    n_e = len(bm.edges)
    bm2 = bm.copy()
    bmesh.ops.remove_doubles(bm2, verts=bm2.verts, dist=1e-5)
    seen = set(); parts2 = 0
    for v in bm2.verts:
        if v.index in seen:
            continue
        parts2 += 1
        stack = [v]; seen.add(v.index)
        while stack:
            a = stack.pop()
            for e in a.link_edges:
                b = e.other_vert(a)
                if b.index not in seen:
                    seen.add(b.index); stack.append(b)
    boundary2 = sum(1 for e in bm2.edges if len(e.link_faces) == 1)
    print("  verts", len(me.vertices), "polys", len(me.polygons), "tris", tris, "loose_parts", parts,
          "boundary_edges", boundary, "of", n_e, "nonmanifold", nonman)
    print("  after merge 1e-5: verts", len(bm2.verts), "parts", parts2, "boundary_edges", boundary2, "of", len(bm2.edges))
    bm.free(); bm2.free()
    ws = [o.matrix_world @ v.co for v in me.vertices]
    print("  bounds min", tuple(round(min(w[i] for w in ws), 4) for i in range(3)),
          "max", tuple(round(max(w[i] for w in ws), 4) for i in range(3)))
    print("  uv", [l.name for l in me.uv_layers], "attrs", [(a.name, a.domain, a.data_type) for a in me.attributes],
          "custom_normals", me.has_custom_normals)
    for m in me.materials:
        print("  MAT", m.name)
        if m and m.node_tree:
            for n in m.node_tree.nodes:
                extra = ""
                if n.type == "TEX_IMAGE" and n.image:
                    extra = n.image.name
                    for out in n.outputs:
                        for l in out.links:
                            extra += " -> %s.%s" % (l.to_node.name, l.to_socket.name)
                if n.type == "BSDF_PRINCIPLED":
                    extra = "metallic %.2f rough %.2f" % (n.inputs["Metallic"].default_value, n.inputs["Roughness"].default_value)
                print("    NODE", n.type, n.name, extra)
for im in bpy.data.images:
    print("IMG", im.name, tuple(im.size), im.channels, im.colorspace_settings.name)

