# Lists the loose panels of the raw GLB around the top rail, and a top-height profile along the gun.
import bpy, bmesh, sys
path = sys.argv[sys.argv.index("--") + 1]
bpy.ops.wm.read_factory_settings(use_empty=True)
bpy.ops.import_scene.gltf(filepath=path)
ob = [o for o in bpy.context.scene.objects if o.type == "MESH"][0]
bm = bmesh.new(); bm.from_mesh(ob.data); bm.faces.ensure_lookup_table()
seen = set(); panels = []
for f in bm.faces:
    if f.index in seen:
        continue
    stack = [f]; seen.add(f.index); comp = []
    while stack:
        a = stack.pop(); comp.append(a)
        for e in a.edges:
            for b in e.link_faces:
                if b.index not in seen:
                    seen.add(b.index); stack.append(b)
    panels.append(comp)
rows = []
for i, comp in enumerate(panels):
    vs = {v for f in comp for v in f.verts}
    lo = [min(v.co[k] for v in vs) for k in range(3)]
    hi = [max(v.co[k] for v in vs) for k in range(3)]
    if hi[2] > 0.075 and lo[2] > 0.06 and hi[1] < 0.2 and lo[0] > -0.04 and hi[0] < 0.03:
        area = sum(f.calc_area() for f in comp)
        up = sum(f.calc_area() * f.normal.z for f in comp) / max(area, 1e-12)
        rows.append((lo[1], i, len(comp), lo, hi, area, up))
for lo1, i, n, lo, hi, area, up in sorted(rows):
    print("PANEL %4d tris %3d  x %.4f..%.4f  y %.4f..%.4f  z %.4f..%.4f  area %.1f cm2  up %.2f" % (
        i, n, lo[0], hi[0], lo[1], hi[1], lo[2], hi[2], area * 1e4, up))
# top profile: max z of vertices near the centre line per 5 mm of Y
prof = {}
for v in bm.verts:
    if abs(v.co.x + 0.0055) < 0.012:
        k = round(v.co.y / 0.005)
        prof[k] = max(prof.get(k, -1), v.co.z)
print("PROFILE", " ".join("%.3f:%.4f" % (k * 0.005, prof[k]) for k in sorted(prof)))

