// Splits a one-file git diff into two patches: hunks that mention the Entity (another chat's work) and the rest.
// Usage: node split_patch.js <full.diff> <mine.diff> <theirs.diff>
const fs = require('fs');
const [full, mineOut, theirsOut] = process.argv.slice(2);
const text = fs.readFileSync(full, 'utf8');
const lines = text.split('\n');
const first = lines.findIndex(l => l.startsWith('@@'));
const header = lines.slice(0, first);
const hunks = [];
for (const line of lines.slice(first)) {
  if (line.startsWith('@@')) hunks.push([line]);
  else hunks[hunks.length - 1].push(line);
}
const mine = [], theirs = [];
hunks.forEach((h, i) => {
  const changed = h.filter(l => /^[+-]/.test(l)).join('\n');
  const isTheirs = /entity|tentacle/i.test(changed);
  (isTheirs ? theirs : mine).push(h);
  console.log('hunk', i + 1, isTheirs ? 'ENTITY' : 'reload', h[0].slice(0, 60), 'changed lines', h.filter(l => /^[+-]/.test(l)).length);
});
const write = (file, list) => fs.writeFileSync(file, header.concat(...list).join('\n').replace(/\n*$/, '\n'));
write(mineOut, mine);
write(theirsOut, theirs);

