// Adds a block before "## Design decisions" in the day entry, numbered after the last "... block:" heading.
// Usage: node add_block.js <block.md> "<package size text>"
const fs = require('fs');
const [blockFile, size] = process.argv.slice(2);
const ORDINALS = ['Twenty-fifth', 'Twenty-sixth', 'Twenty-seventh', 'Twenty-eighth', 'Twenty-ninth', 'Thirtieth',
  'Thirty-first', 'Thirty-second', 'Thirty-third', 'Thirty-fourth', 'Thirty-fifth', 'Thirty-sixth'];
const p = 'C:/GameJam/Devlog/days/2026-11-12.md';
let s = fs.readFileSync(p, 'utf8');
const crlf = s.includes('\r\n');
if (crlf) s = s.split('\r\n').join('\n');
const headings = s.split('\n').filter(l => /^## \S+ block:/.test(l));
const last = headings[headings.length - 1].split(' ')[1];
const index = ORDINALS.indexOf(last);
if (index < 0 || index + 1 >= ORDINALS.length) { console.error('cannot number the block after: ' + last); process.exit(1); }
const block = fs.readFileSync(blockFile, 'utf8').split('\r\n').join('\n')
  .split('ORDINAL').join(ORDINALS[index + 1]).split('PACKAGE_SIZE').join(size);
const anchor = '## Design decisions\n';
if (s.split(anchor).length !== 2) { console.error('anchor not found once'); process.exit(1); }
s = s.split(anchor).join(block + anchor);
if (crlf) s = s.split('\n').join('\r\n');
fs.writeFileSync(p, s);
console.log('added the', ORDINALS[index + 1], 'block after', last);

